"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["42350"],{16682(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_nao_positivo","status":422,"titulo":"O prazo do recurso deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_nao_positivo","requisitos":["UNI-REQ-0113"],"oQueAconteceu":["O prazo declarado pela configura\xe7\xe3o do recurso de uma etapa tem valor zero ou negativo, ou, no prazo de interposi\xe7\xe3o, n\xe3o tem valor. Isso vale para os dois prazos da configura\xe7\xe3o: o de **interposi\xe7\xe3o**, na 1\xaa inst\xe2ncia, e o da **2\xaa inst\xe2ncia**. A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `etapas[i].recursos[j].prazoValor` (interposi\xe7\xe3o) ou `etapas[i].recursos[j].prazoSegundaInstanciaValor` (2\xaa inst\xe2ncia), em que `i` \xe9 a posi\xe7\xe3o da etapa e `j`, a do recurso na etapa.","A mensagem da resposta diz qual dos prazos foi recusado: \\"Informe o prazo de interposi\xe7\xe3o com valor maior que zero.\\" ou \\"Informe o prazo da 2\xaa inst\xe2ncia com valor maior que zero.\\" Um prazo sem valor positivo n\xe3o deixa tempo algum para o candidato recorrer (UNI-REQ-0113). Quando falta o valor do prazo da 2\xaa inst\xe2ncia num recurso que admite inst\xe2ncia superior, a recusa \xe9 a de [prazo da 2\xaa inst\xe2ncia n\xe3o declarado](/erros/uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_segunda_instancia_nao_declarado)."],"comoResolver":["Informe o prazo com valor maior que zero, na unidade que o edital usa: dias \xfateis ou horas. Se o prazo \xe9 menor que um dia, declare-o em horas."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);